"""Report exact source capacity and explicitly hypothetical caption allocations."""
import json
import pandas as pd,yaml
from led_source_token_audit import ROOT,CONFIG
from create_source_length_tie_report import markdown_table


def main():
    cfg=yaml.safe_load(CONFIG.read_text(encoding='utf-8'));out=ROOT/cfg['output_directory']
    validation=json.loads((out/'validation_report.json').read_text());assert validation['validation_passed']
    summary=pd.read_csv(out/'caption_capacity_summary.csv');base=summary[summary.caption_allowance.eq(0)].copy()
    profile='name_categories_location';part=summary[summary.metadata_profile.eq(profile)].copy()
    core=part[['review_budget','caption_allowance','observed_fit','observed_overflow','conservative_envelope_fit','caption_capacity_min','caption_capacity_median','marginal_overhead_max','observed_allocated_total_max','conservative_envelope_total_max']]
    counts=core.to_dict('records');focus=part[part.caption_allowance.eq(750)].set_index('review_budget')
    findings={'businesses':2200,'review_blocks':6600,'source_rows':19800,'audit_profiles':list(cfg['metadata_profiles']),'diagnostic_source_ceiling':5000,'all_text_only_base_inputs_fit':bool(base.source_only_overflows.eq(0).all()),'largest_profile':'name_categories_location','largest_profile_overhead_median':float(focus.loc[4000].marginal_overhead_median),'largest_profile_overhead_p95':float(focus.loc[4000].marginal_overhead_p95),'largest_profile_overhead_max':int(focus.loc[4000].marginal_overhead_max),'caption_capacity_min_by_budget':{str(b):int(focus.loc[b].caption_capacity_min) for b in [3500,4000,4500]},'largest_profile_capacity_scenarios':counts,'pilot_option_not_adopted':{'review_block_budget':4000,'entire_caption_incremental_allowance':750,'observed_businesses_fit':int(focus.loc[4000].observed_fit),'conservative_audited_envelope_fit':int(focus.loc[4000].conservative_envelope_fit),'observed_allocated_total_max':int(focus.loc[4000].observed_allocated_total_max),'conservative_audited_envelope_total_max':int(focus.loc[4000].conservative_envelope_total_max),'why':'Capacity option with improved length balance over3500 while preserving750 caption-block space; no real caption lengths/quality/model/VRAM evidence.','status':'proposal_for_real_caption_pilot_not_final_allocation'},'actual_captions_available':False,'actual_caption_conditioned_source_tokens':None,'metadata_fields_final':None,'final_source_tokens':None,'final_review_tokens':None,'final_caption_tokens':None,'final_manifest':False,'final_selector_locked':False}
    (out/'allocation_findings.json').write_text(json.dumps(findings,indent=2)+'\n',encoding='utf-8')
    examples=pd.read_csv(out/'example_businesses.csv');drops=json.loads((ROOT/cfg['accepted_directory']/'v4_2_count_drop_explanations.json').read_text())
    report=['# LED source token-allocation audit - 2026-10-06','All2200 train/validation businesses, immutable v4.2 complete selections at3500/4000/4500.19800 exact base rows, three provisional metadata profiles. No new selection/test tuning/caption generation/teacher/model/rental/final manifest.','## What was actually measured','Pinned tokenizer, no truncation/padding. Original whole reviews/IDs/order/primary metrics retained. Exact old marked review blocks, full text-only base and empty caption-header structure freshly encoded. BOS/EOS added once per FULL source; component counts are diagnostic, full encoding authoritative. Added metadata fields are audit alternatives, not finalized training inputs; no aggregate ratings/attributes/helpful votes introduced.','## Exact metadata/base capacity',markdown_table(base[['metadata_profile','review_budget','businesses','retained_mean','below10','marginal_overhead_min','marginal_overhead_median','marginal_overhead_p95','marginal_overhead_max','exact_text_base_min','exact_text_base_max','source_only_overflows','caption_capacity_min','caption_capacity_median','caption_capacity_max','empty_caption_header_increment_min','empty_caption_header_increment_max']]),'Marginal overhead is exact full-base minus old marked review-block length. Review block already contains markers/stars/date/separators/specials. Standalone metadata and BODY sum do not form independently additive token blocks because BPE boundaries matter. BODY delta includes formatting/special/boundary effects.','## Hypothetical caption capacity: name/categories/city/state',markdown_table(core),'Caption allowance includes the ENTIRE incremental caption block relative to text-only base, including caption section/line/ID/separator/boundary effects. Zero is text-only control. Positive allowances are budgets, not fake text or measured caption lengths. Actual caption-conditioned source lengths remain null. Observed fits use actual selected blocks; conservative envelope uses declared review_budget plus each measured business overhead plus allowance. Even an all2200 envelope fit is not a universal/test/future-template guarantee.','## Concrete pilot option, still pending',json.dumps(findings['pilot_option_not_adopted'],indent=2),'This is a capacity-based option for review and real caption measurement, not an applied choice.3500+1250 also fits every audited largest-profile case;4500 has less caption room and its positive allowance pressures are explicit above. There is no evidence yet that750 tokens fits the eventual image count/generation/filtering. No k, metadata policy, source limit or research_pending field is frozen.','## Primary representation and count tradeoffs','All count/rating/time/length metrics belong to unchanged review sets, not evaluation of metadata/captions or summary quality. The four existing3500->4000 primary-anchor drops remain unchanged and are separately recorded; an audit allowance removes no review.',json.dumps(drops,indent=2),'V4.2 source BODY median ratios0.765/0.880/0.938 and mean retained28.287/28.437/28.518 remain the accepted comparison. Extra metadata/caption capacity does not prove aspect/summary quality.','## Complete source examples',markdown_table(examples[['name','review_budget','retained_reviews','review_block_tokens','metadata_standalone_tokens','marginal_source_overhead','text_only_base_tokens','caption_capacity']]),'source_examples.json includes nine complete source strings with metadata from originals and unchanged whole selected reviews; separate empty-caption-header illustration, no generated caption. No complete input export for all businesses. These are provisional diagnostics, not teacher/training inputs.','## Independent verification',json.dumps(validation,indent=2),'Two serialization edge checks PASS: Unicode/literal markers/added-special masks/whole texts and deliberately oversized metadata flagged without truncation. Same required original review count can be below10; audit never imposes a minimum. Existing science/sources/configs protected. New scientific artifacts kept small; no dataset copy/bulk candidate cache.','## Decision gates / next step','Review provisional template/primary tradeoffs and capacity option. Validate photos/content duplicates and run an approved small real-caption feasibility pilot, then measure FULL source strings for unfiltered/filtered/shuffled conditions with shared review evidence. Revisit only explicitly approved allocations/template settings if measured caption space is insufficient. Freeze final selector/allocations/shared2300 manifest after required decisions/rechecks; test100 excluded from tuning. No automatic source-length increase or condition-specific review change. LED padding/global attention/decoder/VRAM feasibility and teacher prompts are outside this tokenizer audit. Continue maintained notebook00 section9.6.']
    (out/'source_allocation_report.md').write_text('\n\n'.join(report)+'\n',encoding='utf-8')
    print(json.dumps({k:v for k,v in findings.items() if k!='largest_profile_capacity_scenarios'},indent=2))


if __name__=='__main__':main()
